  const dsh = (x1, y1, x2, y2, col) => '<line x1="' + x1 + '" y1="' + y1 + '" x2="' + x2 + '" y2="' + y2 + '" stroke="' + (col || 'var(--muted)') + '" stroke-width="1.4" stroke-dasharray="4 4"/>';
